var i=`0987-pyongyang-naengmyeon`;var a=`world-0987`;var s=`KP`;var o=`east-asia`;var t=4;var r=132;var g={en:`Pyongyang Naengmyeon`,ua:`Пхеньянський ненмьон`};var l={en:`Pyongyang Naengmyeon is a North Korea dish made with light soy sauce, soba noodles, chicken egg, asian pear. This home-scale recipe assigns measured ingredients to the steps where they are used. Japanese soba stands in for North Korean cold buckwheat noodles.`,ua:`Пхеньянський ненмьон, страва кухні країни Північна Корея. Основні складники: світлий соєвий соус, локшина соба, куряче яйце, азійська груша. Кількості у цьому домашньому рецепті прив’язані до відповідних етапів. Японська соба замінює північнокорейську холодну гречану локшину.`};var m=[{en:`Combine these ingredients in a pot, bring just to a boil and skim any foam. Simmer gently for about 35 minutes to make a flavorful base.`,ua:`З’єднайте складники в каструлі, доведіть майже до кипіння та зніміть піну. Варіть на малому вогні приблизно 35 хвилин для насиченої основи.`,t:[`simmering`,`skimming-foam`],m:35,i:[[`beef-stock`,730,`ml`],[`water`,320,`ml`],[`light-soy-sauce`,45,`ml`]]},{en:`Cool the prepared ingredients promptly, then refrigerate for about 70 minutes until properly chilled.`,ua:`Швидко охолодіть підготовлені складники, потім поставте в холодильник приблизно на 70 хвилин.`,t:[`rapid-chilling`],m:70,i:[[`ice-cubes`,330,`g`]]},{en:`Cook the listed ingredients in simmering water for about 7 minutes until tender; drain well if necessary.`,ua:`Варіть зазначені складники у воді приблизно 7 хвилин до м’якості; за потреби добре злийте воду.`,t:[`boiling`],m:7,i:[[`soba-noodles`,450,`g`],[`water`,1200,`ml`]]},{en:`Boil the eggs for about 10 minutes, cool promptly in cold water, peel and prepare as required.`,ua:`Варіть яйця приблизно 10 хвилин, швидко охолодіть у холодній воді, очистьте та підготуйте за потреби.`,t:[`hard-boiling-eggs`],m:10,i:[[`chicken-egg`,2,`pcs`]]},{en:`Arrange the prepared cooked components and listed toppings in a serving dish, keeping hot foods hot and chilled components cold until serving.`,ua:`Складіть готові приготовлені компоненти й зазначені додатки в посуді для подавання, підтримуючи гаряче гарячим, а холодне охолодженим.`,t:[`layered-assembly`,`garnishing`],m:7,i:[[`asian-pear`,1,`pcs`],[`cucumber`,170,`g`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`rice-vinegar`,25,`ml`]]}];var d={slug:i,id:a,country:`KP`,region:o,servings:4,minutes:132,title:g,text:l,steps:m};export{s as country,d as default,a as id,r as minutes,o as region,t as servings,i as slug,m as steps,l as text,g as title};